#!/usr/bin/env bash
set -euo pipefail

# Points the Swift package at a release's XCFramework and refreshes the Swift
# source generated by UniFFI. Run by the release workflow just before it tags,
# so the Package.swift at tag vX.Y.Z downloads the binary attached to that release.
#
#   ./scripts/update-swift-package.sh <version> <path/to/yorion_engineFFI.xcframework.zip> <path/to/yorion_engine.swift>

cd "$(dirname "$0")/.."

VERSION="${1:?version required, e.g. 0.5.0}"
ZIP="${2:?path to yorion_engineFFI.xcframework.zip required}"
SWIFT_SRC="${3:?path to the generated yorion_engine.swift required}"
REPO="${GITHUB_REPOSITORY:-Yorion-io/yorion_engine}"

if command -v sha256sum >/dev/null 2>&1; then
  CHECKSUM="$(sha256sum "$ZIP" | cut -d' ' -f1)"
else
  CHECKSUM="$(shasum -a 256 "$ZIP" | cut -d' ' -f1)"
fi
URL="https://github.com/${REPO}/releases/download/v${VERSION}/yorion_engineFFI.xcframework.zip"

mkdir -p swift/Sources/YorionEngine
cp "$SWIFT_SRC" swift/Sources/YorionEngine/yorion_engine.swift

sed -e "s|@URL@|${URL}|" -e "s|@CHECKSUM@|${CHECKSUM}|" swift/Package.swift.in > Package.swift

echo "✅ Package.swift → v${VERSION} (checksum ${CHECKSUM})"
